using System;
using System.Linq;
using System.Windows.Forms;
using Point=System.Drawing.Point;
namespace CodeWalker {
 public partial class WorldForm {
  ClxnFlowCard clxnEnvironment;ComboBox clxnSkyPreset,clxnSkyWeather,clxnSkyCloud;NumericUpDown clxnSkyHours,clxnSkyMinutes;CheckBox clxnSkyShown,clxnCloudsShown,clxnGrayShown;volatile bool clxnEnvironmentDirty;
  void ClxnBuildEnvironment(){
   clxnEnvironment=ClxnSidePanel(540);clxnEnvironment.Controls.Add(ClxnStyle.Label("НЕБО И ВРЕМЯ СУТОК",10));clxnEnvironment.Controls.Add(new Label{Width=300,Height=48,Text="Обычный таймцикл GTA V или серый вариант по образцу скриншота.",ForeColor=ClxnStyle.Muted});
   clxnSkyPreset=new ComboBox{Width=300,DropDownStyle=ComboBoxStyle.DropDownList,BackColor=ClxnStyle.Background,ForeColor=ClxnStyle.Text};clxnSkyPreset.Items.AddRange(new object[]{"Обычный · ясный день","Серый · пасмурный день","Серый · ночной смог (по фото)","Обычный · закат","Обычный · ясная ночь"});clxnSkyPreset.SelectedIndex=0;clxnEnvironment.Controls.Add(clxnSkyPreset);clxnEnvironment.Controls.Add(ClxnStyle.Button("Применить готовый вариант",(s,e)=>ClxnApplySkyPreset(),300,true));
   clxnEnvironment.Controls.Add(ClxnStyle.Label("Погода / таймцикл GTA V",9,ClxnStyle.Muted));clxnSkyWeather=new ComboBox{Width=300,DropDownStyle=ComboBoxStyle.DropDownList,BackColor=ClxnStyle.Background,ForeColor=ClxnStyle.Text};clxnEnvironment.Controls.Add(clxnSkyWeather);
   var time=ClxnRow();time.Controls.Add(ClxnStyle.Label("Часы",9));clxnSkyHours=new NumericUpDown{Width=65,Maximum=23};time.Controls.Add(clxnSkyHours);time.Controls.Add(ClxnStyle.Label("Минуты",9));clxnSkyMinutes=new NumericUpDown{Width=65,Maximum=59};time.Controls.Add(clxnSkyMinutes);clxnEnvironment.Controls.Add(time);
   clxnEnvironment.Controls.Add(ClxnStyle.Label("Тип облаков",9,ClxnStyle.Muted));clxnSkyCloud=new ComboBox{Width=300,DropDownStyle=ComboBoxStyle.DropDownList,BackColor=ClxnStyle.Background,ForeColor=ClxnStyle.Text};clxnEnvironment.Controls.Add(clxnSkyCloud);
   clxnSkyShown=new ClxnCheckBox{Text="Показывать небо и светила",AutoSize=true};clxnCloudsShown=new ClxnCheckBox{Text="Объёмные облака",AutoSize=true};clxnEnvironment.Controls.Add(clxnSkyShown);clxnEnvironment.Controls.Add(clxnCloudsShown);clxnGrayShown=new ClxnCheckBox{Text="Серое небо и мягкий свет",AutoSize=true};clxnEnvironment.Controls.Add(clxnGrayShown);
   clxnEnvironment.Controls.Add(ClxnStyle.Button("Применить свои настройки",(s,e)=>ClxnSaveEnvironment(),300));clxnEnvironment.Controls.Add(new Label{Width=300,Height=57,Text="Сохраняется в .clxn и MP4. Серые варианты — приближение на основе погоды GTA V.",ForeColor=ClxnStyle.Muted});
  }
  void ClxnOpenEnvironment(){if(!initialised||!weather.Inited){clxnMessage="Дождитесь загрузки неба и погоды.";return;}clxnLibrary.Visible=clxnWardrobe.Visible=clxnLogPanel.Visible=clxnFlightPanel.Visible=false;clxnSkyWeather.Items.Clear();clxnSkyWeather.Items.AddRange(weather.WeatherTypes.Keys.Cast<object>().ToArray());clxnSkyCloud.Items.Clear();clxnSkyCloud.Items.AddRange(CloudsComboBox.Items.Cast<object>().ToArray());ClxnShowEnvironment();clxnEnvironment.Visible=true;clxnEnvironment.BringToFront();}
  void ClxnShowEnvironment(){if(clxnSkyWeather==null)return;string weatherName=string.IsNullOrEmpty(ClxnProject.SkyWeather)?Renderer.weathertype:ClxnProject.SkyWeather;clxnSkyWeather.SelectedIndex=Enumerable.Range(0,clxnSkyWeather.Items.Count).FirstOrDefault(i=>string.Equals(clxnSkyWeather.Items[i].ToString(),weatherName,StringComparison.OrdinalIgnoreCase));var cloud=string.IsNullOrEmpty(ClxnProject.SkyCloud)?Renderer.individualcloudfrag:ClxnProject.SkyCloud;clxnSkyCloud.SelectedItem=cloud;if(clxnSkyCloud.SelectedIndex<0&&clxnSkyCloud.Items.Count>0)clxnSkyCloud.SelectedIndex=0;float hour=string.IsNullOrEmpty(ClxnProject.SkyWeather)?Renderer.timeofday:ClxnProject.SkyHour;int minutes=(int)Math.Round(hour*60)%1440;clxnSkyHours.Value=minutes/60;clxnSkyMinutes.Value=minutes%60;clxnGrayShown.Checked=ClxnProject.SkyGray;clxnSkyShown.Checked=Renderer.renderskydome;clxnCloudsShown.Checked=Renderer.renderclouds;}
  void ClxnApplySkyPreset(){int index=clxnSkyPreset.SelectedIndex;string desired=index==1?"OVERCAST":index==2?"SMOG":"CLEAR";var match=weather.WeatherTypes.Keys.FirstOrDefault(k=>k.Equals(desired,StringComparison.OrdinalIgnoreCase));if(match==null){clxnMessage="Этот таймцикл не найден в установленной GTA V: "+desired;return;}ClxnRememberEnvironment();ClxnProject.Checkpoint();lock(ClxnProject.Sync){ClxnProject.SkyWeather=match;ClxnProject.SkyHour=index==1?16:index==2?23+56/60f:index==3?19:index==4?0:12;ClxnProject.SkyCloud=index==1||index==2?"":Renderer.individualcloudfrag;ClxnProject.SkyVisible=true;ClxnProject.SkyClouds=index!=1&&index!=2;ClxnProject.SkyGray=index==1||index==2;}ClxnProject.Commit();ClxnApplyEnvironment();ClxnShowEnvironment();clxnMessage="Небо обновлено: "+clxnSkyPreset.Text+". Ctrl+Z — отменить.";}
  void ClxnSaveEnvironment(){if(clxnSkyWeather.SelectedItem==null)return;ClxnRememberEnvironment();ClxnProject.Checkpoint();lock(ClxnProject.Sync){ClxnProject.SkyWeather=clxnSkyWeather.SelectedItem.ToString();ClxnProject.SkyHour=(float)clxnSkyHours.Value+(float)clxnSkyMinutes.Value/60;ClxnProject.SkyCloud=clxnSkyCloud.SelectedItem?.ToString()??"";ClxnProject.SkyVisible=clxnSkyShown.Checked;ClxnProject.SkyClouds=clxnCloudsShown.Checked;ClxnProject.SkyGray=clxnGrayShown.Checked;}ClxnProject.Commit();ClxnApplyEnvironment();clxnMessage="Погода и время сохранены в сцене.";}
  void ClxnRememberEnvironment(){if(!string.IsNullOrEmpty(ClxnProject.SkyWeather))return;lock(RenderSyncRoot)lock(ClxnProject.Sync){ClxnProject.SkyWeather=Renderer.weathertype;ClxnProject.SkyHour=Renderer.timeofday;ClxnProject.SkyCloud=Renderer.individualcloudfrag;ClxnProject.SkyVisible=Renderer.renderskydome;ClxnProject.SkyClouds=Renderer.renderclouds;}}
  void ClxnApplyEnvironment(){if(string.IsNullOrEmpty(ClxnProject.SkyWeather)||!weather.Inited)return;var match=weather.WeatherTypes.Keys.FirstOrDefault(k=>k.Equals(ClxnProject.SkyWeather,StringComparison.OrdinalIgnoreCase));if(match==null){clxnMessage="Таймцикл не найден: "+ClxnProject.SkyWeather;return;}lock(RenderSyncRoot){Renderer.ClxnGraySky=ClxnProject.SkyGray;Renderer.controltimeofday=true;Renderer.controllightdir=false;Renderer.timerunning=false;Renderer.SetTimeOfDay(ClxnProject.SkyHour);Renderer.SetWeatherType(match);Renderer.renderskydome=ClxnProject.SkyVisible;Renderer.renderclouds=ClxnProject.SkyClouds;if(!string.IsNullOrEmpty(ClxnProject.SkyCloud))Renderer.individualcloudfrag=ClxnProject.SkyCloud;}}
 }
}
